/**
 * Official ImageAPI AI SDK
 * https://imageapiai.com
 */

/**
 * Helper to normalize response objects so developers and LLMs
 * can access properties using either camelCase or snake_case without undefined errors.
 */
function normalizeResponse(data) {
  if (!data || typeof data !== 'object') return data;

  if (Array.isArray(data)) {
    return data.map(normalizeResponse);
  }

  const normalized = { ...data };

  // Map known snake_case fields to camelCase
  if (data.image_url !== undefined && data.imageUrl === undefined) normalized.imageUrl = data.image_url;
  if (data.imageUrl !== undefined && data.image_url === undefined) normalized.image_url = data.imageUrl;

  if (data.prompt_id !== undefined && data.promptId === undefined) normalized.promptId = data.prompt_id;
  if (data.promptId !== undefined && data.prompt_id === undefined) normalized.prompt_id = data.promptId;

  if (data.generation_id !== undefined && data.generationId === undefined) normalized.generationId = data.generation_id;
  if (data.generationId !== undefined && data.generation_id === undefined) normalized.generation_id = data.generationId;

  if (data.r2_image_url !== undefined && data.r2ImageUrl === undefined) normalized.r2ImageUrl = data.r2_image_url;
  if (data.r2ImageUrl !== undefined && data.r2_image_url === undefined) normalized.r2_image_url = data.r2_image_url;

  if (data.original_prompt !== undefined && data.originalPrompt === undefined) normalized.originalPrompt = data.original_prompt;
  if (data.originalPrompt !== undefined && data.original_prompt === undefined) normalized.original_prompt = data.originalPrompt;

  if (data.effective_prompt !== undefined && data.effectivePrompt === undefined) normalized.effectivePrompt = data.effective_prompt;
  if (data.effectivePrompt !== undefined && data.effective_prompt === undefined) normalized.effective_prompt = data.effectivePrompt;

  if (data.credits_remaining !== undefined && data.creditsRemaining === undefined) normalized.creditsRemaining = data.credits_remaining;
  if (data.creditsRemaining !== undefined && data.credits_remaining === undefined) normalized.credits_remaining = data.creditsRemaining;

  if (data.credits_deducted !== undefined && data.creditsDeducted === undefined) normalized.creditsDeducted = data.credits_deducted;
  if (data.creditsDeducted !== undefined && data.credits_deducted === undefined) normalized.credits_deducted = data.creditsDeducted;

  if (data.retries_remaining !== undefined && data.retriesRemaining === undefined) normalized.retriesRemaining = data.retries_remaining;
  if (data.retriesRemaining !== undefined && data.retries_remaining === undefined) normalized.retries_remaining = data.retriesRemaining;

  if (data.credit_balance !== undefined && data.creditBalance === undefined) normalized.creditBalance = data.credit_balance;
  if (data.creditBalance !== undefined && data.credit_balance === undefined) normalized.credit_balance = data.creditBalance;

  // Recursively normalize nested data object if present
  if (data.data && typeof data.data === 'object') {
    normalized.data = normalizeResponse(data.data);
  }

  return normalized;
}

class ImageAPI {
  /**
   * Initialize the ImageAPI AI Client.
   * Supports zero-config initialization via environment variables:
   * IMAGEAPIAI_API_KEY or NEXT_PUBLIC_IMAGEAPIAI_API_KEY.
   *
   * @param {Object|string} [config] - Configuration options or raw API key string.
   * @param {string} [config.apiKey] - Your secret API key (sk_live_...).
   * @param {string} [config.baseUrl] - Custom base URL (optional).
   */
  constructor(config = {}) {
    let key;
    let url = 'https://imageapiai.com';

    if (typeof config === 'string') {
      key = config;
    } else {
      key = config.apiKey || config.key;
      if (config.baseUrl) url = config.baseUrl;
    }

    // Auto-discover environment variables across Node, Next.js, Cloudflare, etc.
    if (!key && typeof process !== 'undefined' && process.env) {
      key = process.env.IMAGEAPIAI_API_KEY ||
            process.env.IMAGEAPI_API_KEY ||
            process.env.NEXT_PUBLIC_IMAGEAPIAI_API_KEY;
    }

    if (!key) {
      throw new Error(
        '[ImageAPI] API key is required. Pass it to the constructor or set the IMAGEAPIAI_API_KEY environment variable. Get one at https://imageapiai.com/dashboard'
      );
    }

    this.apiKey = key;
    this.baseUrl = url.replace(/\/$/, '');
  }

  /**
   * Internal HTTP request handler using universal fetch.
   * Compatible with Node.js 18+, Vercel Edge, Cloudflare Workers, Bun, and Deno.
   * @private
   */
  async _request(endpoint, options = {}) {
    const fetchFn = typeof fetch !== 'undefined' ? fetch : globalThis.fetch;
    if (!fetchFn) {
      throw new Error('[ImageAPI] Global fetch is not available in your runtime environment.');
    }

    const url = `${this.baseUrl}${endpoint}`;
    const headers = {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${this.apiKey}`,
      ...options.headers
    };

    const response = await fetchFn(url, { ...options, headers });
    let data;

    try {
      data = await response.json();
    } catch (_) {
      throw new Error(`[ImageAPI Error]: Request failed with HTTP status ${response.status}`);
    }

    if (!response.ok || !data.success) {
      throw new Error(data.error || `[ImageAPI Error]: Request failed with status ${response.status}`);
    }

    return normalizeResponse(data);
  }

  /**
   * Generate an image from a prompt or refine an existing image.
   * Supports shorthand string syntax: client.generate("a cute cat")
   *
   * @param {string|Object} params - Prompt string or options object.
   * @param {string} [params.prompt] - Text prompt describing the image.
   * @param {number} [params.width=512] - Image width in pixels.
   * @param {number} [params.height=512] - Image height in pixels.
   * @param {('low'|'medium'|'high')} [params.quality='medium'] - Generation inference quality.
   * @param {string} [params.parentPromptId] - (or parent_prompt_id) ID of existing image to refine for 0 credits.
   * @param {string} [params.promptUpdate] - (or prompt_update) Modification to append to base prompt.
   * @returns {Promise<Object>} Generation response payload with normalized keys.
   */
  async generate(params) {
    if (!params) {
      throw new Error('[ImageAPI] Prompt or parameters object is required.');
    }

    let payload = {};

    // Shorthand string support: client.generate("A neon skyline")
    if (typeof params === 'string') {
      payload = { prompt: params, quality: 'medium' };
    } else {
      const prompt = params.prompt;
      const parentId = params.parentPromptId || params.parent_prompt_id;
      const promptUpdate = params.promptUpdate || params.prompt_update;
      const quality = (params.quality || 'medium').toLowerCase();

      if (!prompt && !parentId) {
        throw new Error('[ImageAPI] Either "prompt" or "parentPromptId" must be provided.');
      }

      payload = {
        prompt,
        quality,
        parent_prompt_id: parentId,
        prompt_update: promptUpdate
      };

      if (params.width) payload.width = params.width;
      if (params.height) payload.height = params.height;
    }

    return await this._request('/v1/images/generate', {
      method: 'POST',
      body: JSON.stringify(payload)
    });
  }

  /**
   * Convenience method to refine/retry an existing image prompt for 0 credits.
   *
   * @param {string} parentPromptId - The prompt_id/generation_id of the base image.
   * @param {string} promptUpdate - Details or style additions to append to the base prompt.
   * @param {Object} [options] - Optional dimensional/quality overrides.
   * @returns {Promise<Object>} Refined image output.
   */
  async refine(parentPromptId, promptUpdate, options = {}) {
    if (!parentPromptId || !promptUpdate) {
      throw new Error('[ImageAPI] Both parentPromptId and promptUpdate are required for refining an image.');
    }

    return await this.generate({
      parent_prompt_id: parentPromptId,
      prompt_update: promptUpdate,
      width: options.width,
      height: options.height,
      quality: options.quality || 'medium'
    });
  }

  /**
   * Retrieve the current user's profile, credits balance, and subscription status.
   * @returns {Promise<Object>} Profile payload.
   */
  async getProfile() {
    return await this._request('/v1/users/me', { method: 'GET' });
  }

  /**
   * Retrieve generation history for the authenticated account.
   * @returns {Promise<Object>} Array of historical generation records.
   */
  async getHistory() {
    return await this._request('/v1/images/history', { method: 'GET' });
  }
}

module.exports = ImageAPI;
module.exports.default = ImageAPI;
module.exports.ImageAPI = ImageAPI;